insert into practice_exercises (id, subject_name, level, title, source) values
  ('8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$Natuurkunde$$, $$HAVO$$, $$Lutetium-177$$, $$HAVO Natuurkunde 2021-III$$),
  ('acdffc73-9ebd-465a-a6c2-aebad8a34065', $$Natuurkunde$$, $$HAVO$$, $$Accuboormachine$$, $$HAVO Natuurkunde 2021-III$$),
  ('d9f5f7f2-c623-40aa-afae-10202224f538', $$Natuurkunde$$, $$HAVO$$, $$Solderen$$, $$HAVO Natuurkunde 2021-III$$),
  ('658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$Natuurkunde$$, $$HAVO$$, $$Mondharp$$, $$HAVO Natuurkunde 2021-III$$),
  ('119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$Natuurkunde$$, $$HAVO$$, $$Wereldrecord Usain Bolt$$, $$HAVO Natuurkunde 2021-III$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('84508e59-31a7-49a1-b8c0-827c7d7fbe10', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$intro: Lu-177 in lutetium-octreotaat vervalt door β− en γ-straling$$, $$natuurkunde-havo-2021-iii-lutetium-177-context1.png$$, 526, $$Lutetium-octreotaat is een radioactief eiwit waarmee patiënten met diepliggende tumoren inwendig en lokaal bestraald kunnen worden. In dit eiwit wordt de radioactieve isotoop Lu-177 gebruikt. Lu-177 vervalt door het uitzenden van β− en γ-straling.$$, 'inline'),
  ('04ec26eb-e7eb-4438-9741-64b26302a216', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$straling van Lu-177 moet buiten het lichaam opgevangen kunnen worden$$, $$natuurkunde-havo-2021-iii-lutetium-177-context2.png$$, 526, $$De straling die door Lu-177 wordt uitgezonden, wordt gebruikt om de tumoren in het weefsel te vernietigen, maar ook om te kijken of de tumor het lutetium goed heeft opgenomen. Daarvoor is het belangrijk dat de straling die Lu-177 uitzendt buiten het lichaam kan worden opgevangen.$$, 'inline'),
  ('cf302164-ebf8-4889-86ae-d0ddd857f9ff', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$energie van de straling van Lu-177: 7,05·10⁻¹⁴ J$$, $$natuurkunde-havo-2021-iii-lutetium-177-context3.png$$, 526, $$Lu-177 zendt straling uit met een energie van 7,05·10⁻¹⁴ J.$$, 'inline'),
  ('7b82e845-bca7-4504-836c-0f177e5c0e88', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$activiteit afgenomen tot 0,001-ste deel; halveringstijd 6,7 dagen$$, $$natuurkunde-havo-2021-iii-lutetium-177-context4.png$$, 526, $$Bij een patiënt wordt bij een behandeling een hoeveelheid Lu-177 in de bloedsomloop gebracht. Als de activiteit van het Lu-177 is afgenomen tot 0,001-ste deel van de oorspronkelijke activiteit, moet de patiënt in het ziekenhuis terugkomen. De halveringstijd van Lu-177 is 6,7 dagen.$$, 'inline'),
  ('b1676376-caf4-49c4-9838-dd29416d33a2', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$leefregels na therapie (1 m/2 m afstand); intensiteit omgekeerd kwadratisch met de afstand$$, $$natuurkunde-havo-2021-iii-lutetium-177-context5.png$$, 526, $$Als de patiënt naar huis gaat krijgt hij leefregels mee: de patiënt is immers radioactief. In de folder van een ziekenhuis staat:

Algemene leefregels voor thuis na therapie met radioactief lutetium
− U moet afstand bewaren tot uw huisgenoten en bezoekers: minimaal één meter, liefst meer. Het is aan te bevelen dat u en uw partner apart slapen op minstens twee meter afstand van elkaar, indien mogelijk in aparte kamers.

De intensiteit van de straling van de γ-straling is omgekeerd kwadratisch evenredig met de afstand.$$, 'inline'),
  ('18bc2c24-3a93-43be-ab38-e46e044816ec', '8420400e-77e9-4fe6-9a5e-56ddd41316f7', $$muur tussen slaapkamers: beton, 10,5 cm dik$$, $$natuurkunde-havo-2021-iii-lutetium-177-context6.png$$, 526, $$In de ''Algemene leefregels'' staat dat het voor de patiënt en zijn partner wordt aangeraden om in een aparte kamer te slapen. Een muur tussen twee slaapkamers is van beton en 10,5 cm dik.$$, 'inline'),
  ('0bcf9410-83c6-44f8-b3f2-8d6586acd42a', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$figuur 1: tabel met capaciteit, spanning, vermogen, koppel; definitie van capaciteit (Ah)$$, $$natuurkunde-havo-2021-iii-accuboormachine-context1.png$$, 526, $$Inge gebruikt regelmatig een accuboormachine. Het valt haar op dat deze boormachine niet voor iedere boorklus geschikt is. Zij wil weten hoe dat komt en besluit daarom enkele eigenschappen van de boormachine te onderzoeken.

Op de doos van de boormachine staat een tabel met eigenschappen van de boormachine. Zie figuur 1.

figuur 1: foto van de accuboormachine naast een tabel met de eigenschappen capaciteit (1,3 Ah), spanning (10,8 V), (maximaal) vermogen (180 W) en (maximaal) koppel (16 Nm).

Inge is vergeten wat capaciteit betekent. Ze zoekt op internet en vindt het volgende:

''Met capaciteit wordt bedoeld hoeveel stroomsterkte de accu gedurende een bepaalde tijd kan leveren. 3,0 Ah betekent dat de accu gedurende één uur 3,0 A kan leveren, of 1,5 A gedurende twee uur.''$$, 'inline'),
  ('b974d3c9-ce5e-47e7-b5fa-4c6b74cd74c2', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$figuur 2: lampje bij de boorkop; eisen aan de schakeling voor motor en lampje$$, $$natuurkunde-havo-2021-iii-accuboormachine-context2.png$$, 526, $$Sommige accuboormachines zijn voorzien van een lampje dat de plek verlicht waar geboord wordt. Zie figuur 2.

figuur 2: foto van een accuboormachine met een lampje dat de boorkop verlicht.

De schakeling hiervoor voldoet aan de volgende eisen:
− Als de motor van de boor met een schakelaar wordt ingeschakeld, gaat het lampje ook branden.
− Door het lampje loopt een kleine stroomsterkte, door de motor loopt een grote stroomsterkte.
Op de uitwerkbijlage zijn vijf verschillende schakelingen getekend.$$, 'inline'),
  ('bdfd85e8-6b9a-47a6-bfda-5d84e17f0f83', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$uitwerkbijlage vraag 8 — vijf schakelingen (I t/m V) met motor M, lampje en schakelaar$$, $$natuurkunde-havo-2021-iii-accuboormachine-uitwerkbijlage-vraag8.png$$, 526, $$Uitwerkbijlage vraag 8: vijf schakelschema''s (I, II, III, IV en V), elk met een spanningsbron, een lampje, een motor M en een schakelaar in verschillende onderlinge combinaties van serie- en parallelschakeling. Bij elke schakeling moet de leerling ''wel'' of ''niet'' omcirkelen om aan te geven of de schakeling aan de gestelde eisen voldoet.$$, 'uitwerkbijlage'),
  ('36440801-787e-4ae0-a51b-615ec3fb6969', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$boortje diameter 10 mm; toerental 1500 opm bij vrij draaien$$, $$natuurkunde-havo-2021-iii-accuboormachine-context3.png$$, 526, $$Inge monteert een boortje met een diameter van 10 mm in de boormachine. Als de boormachine vrij draait, is het toerental 1500 omwentelingen per minuut.$$, 'inline'),
  ('9ff5533f-99df-4568-a2c7-17b44d27fcbb', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$toerental wordt minder bij hardere houtsoorten; P = Fv$$, $$natuurkunde-havo-2021-iii-accuboormachine-context4.png$$, 526, $$Inge boort gaatjes in verschillende houtsoorten. Ze merkt dat de boormachine bij hardere houtsoorten minder toeren maakt. Ze neemt aan dat de boormachine wel steeds hetzelfde maximale vermogen levert.$$, 'inline'),
  ('6099ebd4-0d02-4670-a831-10d793b862c1', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$definitie van het koppel (F·d) van een boormachine; gat van 15 mm, koppel 16 Nm$$, $$natuurkunde-havo-2021-iii-accuboormachine-context5.png$$, 526, $$Als Inge gaten boort in verschillende materialen, merkt ze dat de maximale diameter van het gat afhangt van de hardheid van het materiaal. Ze veronderstelt dat dit te maken heeft met het maximale koppel van de boormachine. Zij gaat op zoek naar uitleg over het koppel van een boormachine.
Ze vindt de volgende definitie van het koppel van een boormachine:

''Het koppel van de boormachine is de kracht F die op het uiteinde van een boorgat wordt uitgeoefend, vermenigvuldigd met de diameter d van het boorgat.''

figuur (in kader): bovenaanzicht van een boorgat in hout met de diameter d aangegeven en twee tegengesteld gerichte krachtpijlen F loodrecht op de diameter, aan weerszijden van de cirkelrand.

Inge boort een gat met een diameter van 15 mm. Het koppel van haar boor is 16 Nm.$$, 'inline'),
  ('11609eae-4d5e-4da4-a331-d750ffb8a0d7', 'acdffc73-9ebd-465a-a6c2-aebad8a34065', $$bewering op internetforum over koppel en diameter van het boorgat$$, $$natuurkunde-havo-2021-iii-accuboormachine-context6.png$$, 526, $$Op een internetforum ziet zij dat iemand beweert:

''Als het koppel van een boormachine niet verandert, geldt: hoe groter de diameter van het boorgat, hoe groter de kracht aan de rand van het gat.''$$, 'inline'),
  ('edc3a9dd-149b-4435-91aa-e24c1bc61826', 'd9f5f7f2-c623-40aa-afae-10202224f538', $$solderen met zacht soldeer (lager smeltpunt); soldeerbout 15 A, 90 W, 230 V$$, $$natuurkunde-havo-2021-iii-solderen-context1.png$$, 526, $$Solderen is een techniek om twee metalen onderdelen met elkaar te verbinden. In figuur 1 zie je hoe een onderdeel wordt gesoldeerd.

figuur 1: zwart-witfoto van het solderen van een elektronicaonderdeel — de punt van een soldeerbout brengt smeltend soldeer aan op de pootjes van een chip op een printplaat.

Voor het solderen wordt de alliage (mengsel van metalen) ''zacht soldeer'' gebruikt. Deze alliage heeft een lager smeltpunt dan de metalen onderdelen die met elkaar verbonden moeten worden.

Er wordt een messingdraad met zacht soldeer aan een messingstrip gesoldeerd. Het solderen gebeurt met (de punt van) een soldeerbout. Zie figuur 2.

figuur 2: foto van een soldeerstation met een soldeerbout in een houder en een reinigingssponsje.

In de soldeerbout loopt een elektrische stroomsterkte van 15 A.
Het elektrische vermogen is 90 W.
Het soldeerapparaat is aangesloten op een stopcontact met een spanning van 230 V.$$, 'inline'),
  ('8c0a4878-c162-4de0-9933-4f41c048dd1f', 'd9f5f7f2-c623-40aa-afae-10202224f538', $$transformator in het soldeerapparaat wordt tijdens gebruik ook een beetje warm$$, $$natuurkunde-havo-2021-iii-solderen-context2.png$$, 526, $$Via de transformator wordt de energie die uit het stopcontact komt getransporteerd naar de punt. Tijdens het gebruik wordt ook de transformator een beetje warm.$$, 'inline'),
  ('ea928812-65ec-4cd9-8259-aee0cce26698', 'd9f5f7f2-c623-40aa-afae-10202224f538', $$soldeerbout: doeltemperatuur 400 °C, begintemperatuur 20 °C, koperen punt van 50 gram$$, $$natuurkunde-havo-2021-iii-solderen-context3.png$$, 526, $$De soldeerbout is te gebruiken als de temperatuur van de punt 400 °C is. De begintemperatuur is 20 °C. De punt is gemaakt van koper en heeft een massa van 50 gram.$$, 'inline'),
  ('24fbccf9-73a7-46db-a26a-ea13c2a8ce56', 'd9f5f7f2-c623-40aa-afae-10202224f538', $$figuur 3: tang beschermt klein onderdeel tegen oververhitting tijdens het solderen$$, $$natuurkunde-havo-2021-iii-solderen-context4.png$$, 526, $$Bij het solderen van een klein onderdeel wordt vaak een metalen tang gebruikt, om dit onderdeel te beschermen tegen oververhitting. Zie figuur 3. Het materiaal van de punt van de tang is hierbij van belang. Op de uitwerkbijlage staan hierover twee zinnen.

figuur 3: foto van twee handen die met een soldeerbout en een metalen tang een klein onderdeel op een printplaat solderen; de tang houdt het onderdeel vast tijdens het solderen.$$, 'inline'),
  ('6ed46f53-a475-4f1c-9576-4ee1e1d86d1c', 'd9f5f7f2-c623-40aa-afae-10202224f538', $$uitwerkbijlage vraag 17 — twee zinnen met aan te kruisen alternatieven over de tangpunt$$, $$natuurkunde-havo-2021-iii-solderen-uitwerkbijlage-vraag17.png$$, 526, $$Uitwerkbijlage vraag 17: ''De warmtegeleidingscoëfficiënt van het materiaal van de punt van de tang moet groot zijn / moet klein zijn / is niet van belang.'' en ''De soortelijke weerstand van het materiaal van de punt van de tang moet groot zijn / moet klein zijn / is niet van belang.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('37ce64df-5d66-48c8-b843-de59d47fdb21', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$figuur 1-3: trilplaatje van de mondharp tegen de tanden; (u,t)-diagram van de trilling$$, $$natuurkunde-havo-2021-iii-mondharp-context1.png$$, 526, $$Een mondharp is een muziekinstrumentje met een metaalplaatje dat maar aan één kant vast zit. Dit metaalplaatje kan als ''trilplaatje'' gebruikt worden, zie figuur 1. Het instrumentje wordt met de pootjes tegen de voortanden gezet. Zie figuur 2. Door het metaalplaatje aan te slaan, gaat het plaatje trillen en produceert een grondtoon.

figuur 1: foto van een mondharp — een metalen frame met pootjes en een los trilplaatje in het midden dat aan één kant vastzit.
figuur 2: foto van een mondharp die met de pootjes tegen de voortanden wordt gehouden, met een vinger die het trilplaatje aanslaat.

Met behulp van een computermeting kan een (u,t)-diagram van de trilling van het metaalplaatje worden gemaakt. Het diagram hiervan is weergegeven in figuur 3. Hierin is de uitwijking uitgezet tegen de tijd. Op de uitwerkbijlage is figuur 3 nogmaals gegeven.

figuur 3: (u,t)-diagram van de trilling van het metaalplaatje; u (cm) op de verticale as van −0,20 tot 0,30, t (s) op de horizontale as van ongeveer 0,19 tot 0,305 met schaalverdeling per 0,02 s; een gedempte trilling met pieken die geleidelijk in hoogte afnemen van ongeveer 0,28 cm naar 0,20 cm, met rond t = 0,255 s één opvallend hogere piek van circa 0,33 cm.$$, 'inline'),
  ('51f659bf-4410-4903-83b3-aa7fabeea9a8', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$uitwerkbijlage vraag 18 — figuur 3 herhaald, met invulruimte voor de bepaling$$, $$natuurkunde-havo-2021-iii-mondharp-uitwerkbijlage-vraag18.png$$, 526, $$Uitwerkbijlage vraag 18: figuur 3 (het (u,t)-diagram van de trilling van het metaalplaatje) nogmaals afgebeeld, gevolgd door invulregels bij ''Bepaling:'' voor het bepalen van de frequentie van de grondtoon.$$, 'uitwerkbijlage'),
  ('b9b6e210-e2eb-4228-ab9a-8d39cdd6490d', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$andere mondharp: metaalplaatje 8,5 cm × 3,5 mm × 0,50 mm, van staal$$, $$natuurkunde-havo-2021-iii-mondharp-context2.png$$, 526, $$Een andere mondharp heeft een metaalplaatje van 8,5 cm lang, 3,5 mm breed en 0,50 mm dik. Het metaalplaatje is gemaakt van staal.$$, 'inline'),
  ('f949381f-423a-4d92-a77c-878b4e644606', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$formule grondtoonfrequentie fg = c·v·d/l² met betekenis van de grootheden$$, $$natuurkunde-havo-2021-iii-mondharp-context3.png$$, 526, $$De frequentie van de grondtoon van het metaalplaatje wordt gegeven door:

fg = c·(v·d)/l²

Hierin is:
− fg de frequentie in Hz;
− v de geluidssnelheid in het materiaal van het metaalplaatje in m s−1;
− d de dikte van het metaalplaatje in m;
− l de lengte van het metaalplaatje in m;
− c een constante, met een waarde van 0,162.$$, 'inline'),
  ('4dffb68e-ffdc-40cc-aafc-6c8992a870d1', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$een mondharp produceert naast de grondtoon ook boventonen$$, $$natuurkunde-havo-2021-iii-mondharp-context4.png$$, 526, $$Naast de grondtoon produceert een mondharp ook boventonen.$$, 'inline'),
  ('8b5bb6b9-67bc-44da-898f-42e6c67f1460', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$figuur 4A/4B: mond- en keelholte als luchtkolom met open en gesloten uiteinde$$, $$natuurkunde-havo-2021-iii-mondharp-context5.png$$, 526, $$Een mondharp gebruikt de mondholte en keelholte als klankkast. Deze holtes vormen samen een luchtkolom met een open en een gesloten uiteinde. Door de lengte van deze luchtkolom te veranderen, verandert de klank van de toon, omdat verschillende tonen versterkt worden. Zie figuur 4A en 4B.
In figuur 4A is de keelholte open. In figuur 4B staat de mondholte niet meer in verbinding met de keelholte.

figuur 4A: doorsnedetekening van hoofd en hals met een open luchtkolom die loopt van de mondopening tot in de open keelholte.
figuur 4B: dezelfde doorsnede, maar de keelholte is hier afgesloten van de mondholte, zodat de luchtkolom alleen de mondholte omvat.$$, 'inline'),
  ('8854efc9-7ebe-452a-9e4e-c34878cbdb26', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$lengte mond- en keelholte 17 cm, gelijk aan kwart golflengte; temperatuur 313 K$$, $$natuurkunde-havo-2021-iii-mondharp-context6.png$$, 526, $$De lengte van de mond- en keelholte tot aan de stembanden is 17 cm. Deze lengte is gelijk aan een kwart van de golflengte. De temperatuur van de lucht in de mond en de keel is 313 K.$$, 'inline'),
  ('a42f2526-b7fa-4d62-bace-b63af6296180', '658a3e46-44d8-47cc-8a1a-97e52f0de98e', $$uitwerkbijlage vraag 22 — tekening van het trilplaatje om knopen K en buiken B in te tekenen$$, $$natuurkunde-havo-2021-iii-mondharp-uitwerkbijlage-vraag22.png$$, 526, $$Uitwerkbijlage vraag 22: foto van het losse metalen trilplaatje van de mondharp (zijaanzicht, aan één kant vastgeklemd in het frame), waarin de leerling de plaats van de knopen K en de buiken B moet aangeven voor de eerste boventoon.$$, 'uitwerkbijlage'),
  ('95d619e1-49f8-4433-bc86-1fdbc2fce399', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$figuur 1: (t,x)-diagram van de 100 m sprint van Usain Bolt (WK 2009)$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-context1.png$$, 526, $$Tijdens de wereldkampioenschappen van 2009 in Berlijn liep Usain Bolt een nieuw wereldrecord op de 100 m sprint. Medewerkers van de Internationale Atletiek Federatie (IAF) hebben bij deze race niet alleen de eindtijd gemeten, maar ook de tijd na 20 m, 40 m, 60 m, en 80 m. De metingen zijn uitgezet in een (t,x)-diagram, zie figuur 1.

figuur 1: (t,x)-diagram van de 100 m sprint; t (s) op de verticale as van 0 tot 10, x (m) op de horizontale as van 0 tot 100; een kromme door de oorsprong die steeds minder steil stijgt en na x ≈ 30 m nagenoeg recht doorloopt, met gemeten punten bij (20; 2,87), (40; 4,65), (60; 6,31), (80; 7,92) en (100; 9,58).$$, 'inline'),
  ('2fcc397d-7857-4c5c-9a19-68a34bae5b53', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$IAF-bewering: topsnelheid van bijna 45 km/h$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-context2.png$$, 526, $$Het team van de IAF beweerde dat Usain Bolt tijdens zijn race een snelheid haalde van bijna 45 km h⁻¹.$$, 'inline'),
  ('01d66b4d-58b8-497b-b93a-fda8c50e2f45', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$eerste 20 m in 2,86 s, snelheid 10 m/s na dit interval, massa 93 kg$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-context3.png$$, 526, $$Usain Bolt legde de eerste 20 m af in 2,86 s. Hij had na dit interval een snelheid van 10 m s⁻¹. De metingen toonden aan dat Bolt in dit interval niet eenparig versnelde vanaf stilstand.
Usain Bolt heeft een massa van 93 kg.$$, 'inline'),
  ('8fcf4a69-b05d-42bd-89e7-44b4af809d84', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$figuur 2: afzetkracht bij de start; definitie van efficiëntie$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-context4.png$$, 526, $$Tijdens de start zetten sprinters zich schuin naar voren af. Alleen de horizontale component van de afzetkracht wordt gebruikt om de atleet te versnellen over de baan. In de biomechanica wordt de verhouding van de horizontale component ten opzichte van de totale afzetkracht de efficiëntie genoemd.
In figuur 2 is de totale afzetkracht met een vectorpijl weergegeven. Deze figuur staat vergroot op de uitwerkbijlage.

figuur 2: foto van een sprinter (Usain Bolt) die net uit de startblokken vertrekt, met een vectorpijl vanaf de voet in het startblok die schuin naar voren en omhoog wijst en de totale afzetkracht voorstelt.$$, 'inline'),
  ('e9bc3a26-822d-4698-b3a4-5f997df7bbe6', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$estafette: alleen de eerste loper vertrekt vanuit stilstand$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-context5.png$$, 526, $$Usain Bolt deed ook mee in de estafetteploeg. Hierbij moet alleen de eerste sprinter vanuit stilstand vertrekken. De overige sprinters mogen al snelheid maken voor ze aan hun 100 m beginnen. Bij de estafette vertrok Usain Bolt niet als eerste.
Op de uitwerkbijlage is figuur 1 nogmaals weergegeven.$$, 'inline'),
  ('51a72c93-8419-42f0-ad7f-7d440b153c20', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$uitwerkbijlage vraag 28 — vergrote foto met afzetkrachtpijl, invulruimte voor de bepaling$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-uitwerkbijlage-vraag28.png$$, 526, $$Uitwerkbijlage vraag 28: vergrote versie van figuur 2 — de foto van de sprinter bij de start met de vectorpijl van de totale afzetkracht vanaf de voet in het startblok — gevolgd door invulregels bij ''Bepaling:'' voor het bepalen van de efficiëntie.$$, 'uitwerkbijlage'),
  ('1782c930-6d90-42f3-a718-02d61cfb04f8', '119bc0c4-3286-4a51-9dc9-b8c1cdb371d4', $$uitwerkbijlage vraag 29 — figuur 1 herhaald, met invulruimte voor de toelichting$$, $$natuurkunde-havo-2021-iii-wereldrecord-usain-bolt-uitwerkbijlage-vraag29.png$$, 526, $$Uitwerkbijlage vraag 29: figuur 1 (het (t,x)-diagram van de 100 m sprint) nogmaals afgebeeld, gevolgd door invulregels bij ''Toelichting:'' voor het toelichten van de berekende tijdswinst.$$, 'uitwerkbijlage');

